SELECT (COUNT(?c) AS ?n) WHERE {
  ?c a <http://bird-bird_financial-ontology-20260804-131042/ontology/vkg-bird_financial/Client> ;
     <http://bird-bird_financial-ontology-20260804-131042/ontology/vkg-bird_financial/Client/gender> ?gender .
  FILTER(?gender = "M")
}

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (COUNT(?client) AS ?n) WHERE {
  ?client a <http://bird-bird_financial-ontology-20260804-131042/ontology/vkg-bird_financial/Client> ;
          <http://bird-bird_financial-ontology-20260804-131042/ontology/vkg-bird_financial/Client/gender> "F" ;
          <http://bird-bird_financial-ontology-20260804-131042/ontology/vkg-bird_financial/Client/birth_date> ?bd .
  FILTER (?bd < "1950-01-01"^^xsd:date)
}

SELECT DISTINCT ?account_id WHERE {
  {
    SELECT (MAX(?bd) AS ?maxbd) WHERE {
      ?c a <http://bird-bird_financial-ontology-20260804-131042/ontology/vkg-bird_financial/Client> ;
         <http://bird-bird_financial-ontology-20260804-131042/ontology/vkg-bird_financial/Client/birth_date> ?bd .
    }
  }
  ?c2 a <http://bird-bird_financial-ontology-20260804-131042/ontology/vkg-bird_financial/Client> ;
      <http://bird-bird_financial-ontology-20260804-131042/ontology/vkg-bird_financial/Client/birth_date> ?maxbd ;
      <http://bird-bird_financial-ontology-20260804-131042/ontology/vkg-bird_financial/Client/client_id> ?cid .
  ?d a <http://bird-bird_financial-ontology-20260804-131042/ontology/vkg-bird_financial/Disp> ;
     <http://bird-bird_financial-ontology-20260804-131042/ontology/vkg-bird_financial/Disp/client_id> ?cid ;
     <http://bird-bird_financial-ontology-20260804-131042/ontology/vkg-bird_financial/Disp/account_id> ?account_id .
}

SELECT (COUNT(DISTINCT ?district) AS ?n) WHERE {
  ?client a <http://bird-bird_financial-ontology-20260804-131042/ontology/vkg-bird_financial/Client> ;
          <http://bird-bird_financial-ontology-20260804-131042/ontology/vkg-bird_financial/Client/gender> "F" ;
          <http://bird-bird_financial-ontology-20260804-131042/ontology/vkg-bird_financial/Client/hasDistrict> ?district .
}

SELECT ?account_id WHERE {
  ?client a <http://bird-bird_financial-ontology-20260804-131042/ontology/vkg-bird_financial/Client> ;
    <http://bird-bird_financial-ontology-20260804-131042/ontology/vkg-bird_financial/Client/gender> "F" ;
    <http://bird-bird_financial-ontology-20260804-131042/ontology/vkg-bird_financial/Client/birth_date> ?bd ;
    <http://bird-bird_financial-ontology-20260804-131042/ontology/vkg-bird_financial/Client/client_id> ?cid .
  ?disp a <http://bird-bird_financial-ontology-20260804-131042/ontology/vkg-bird_financial/Disp> ;
    <http://bird-bird_financial-ontology-20260804-131042/ontology/vkg-bird_financial/Disp/client_id> ?cid ;
    <http://bird-bird_financial-ontology-20260804-131042/ontology/vkg-bird_financial/Disp/account_id> ?account_id .
}
ORDER BY ASC(?bd)
LIMIT 1

SELECT (100.0 * SUM(IF(?status = "A", xsd:decimal(?amount), 0.0)) / SUM(?amount) AS ?pct)
WHERE {
  ?l a <http://bird-bird_financial-ontology-20260804-131042/ontology/vkg-bird_financial/Loan> ;
     <http://bird-bird_financial-ontology-20260804-131042/ontology/vkg-bird_financial/Loan/amount> ?amount ;
     <http://bird-bird_financial-ontology-20260804-131042/ontology/vkg-bird_financial/Loan/status> ?status .
}

SELECT (100.0 * SUM(IF(?status = "C", 1, 0)) / COUNT(*) AS ?percentage)
WHERE {
  ?loan a <http://bird-bird_financial-ontology-20260804-131042/ontology/vkg-bird_financial/Loan> ;
        <http://bird-bird_financial-ontology-20260804-131042/ontology/vkg-bird_financial/Loan/amount> ?amount ;
        <http://bird-bird_financial-ontology-20260804-131042/ontology/vkg-bird_financial/Loan/status> ?status .
  FILTER (xsd:decimal(?amount) < 100000)
}

SELECT ?district (COUNT(?client) AS ?femaleHolders) WHERE {
  ?client a <http://bird-bird_financial-ontology-20260804-131042/ontology/vkg-bird_financial/Client> ;
          <http://bird-bird_financial-ontology-20260804-131042/ontology/vkg-bird_financial/Client/gender> "F" ;
          <http://bird-bird_financial-ontology-20260804-131042/ontology/vkg-bird_financial/Client/hasDistrict> ?district .
  ?disp a <http://bird-bird_financial-ontology-20260804-131042/ontology/vkg-bird_financial/Disp> ;
        <http://bird-bird_financial-ontology-20260804-131042/ontology/vkg-bird_financial/Disp/hasClient> ?client ;
        <http://bird-bird_financial-ontology-20260804-131042/ontology/vkg-bird_financial/Disp/type> "OWNER" .
}
GROUP BY ?district
ORDER BY DESC(?femaleHolders)
LIMIT 9

