        <http://bird-bird_financial-ontology-20260804-131042/ontology/vkg-bird_financial/Loan/date> "1993-07-05"^^xsd:date ;
        <http://bird-bird_financial-ontology-20260804-131042/ontology/vkg-bird_financial/Loan/account_id> ?accId .

  ?transStart a <http://bird-bird_financial-ontology-20260804-131042/ontology/vkg-bird_financial/Trans> ;
        <http://bird-bird_financial-ontology-20260804-131042/ontology/vkg-bird_financial/Trans/account_id> ?accId ;
        <http://bird-bird_financial-ontology-20260804-131042/ontology/vkg-bird_financial/Trans/date> "1993-03-22"^^xsd:date ;
        <http://bird-bird_financial-ontology-20260804-131042/ontology/vkg-bird_financial/Trans/balance> ?balStart .

  ?transEnd a <http://bird-bird_financial-ontology-20260804-131042/ontology/vkg-bird_financial/Trans> ;
        <http://bird-bird_financial-ontology-20260804-131042/ontology/vkg-bird_financial/Trans/account_id> ?accId ;
        <http://bird-bird_financial-ontology-20260804-131042/ontology/vkg-bird_financial/Trans/date> "1998-12-27"^^xsd:date ;
        <http://bird-bird_financial-ontology-20260804-131042/ontology/vkg-bird_financial/Trans/balance> ?balEnd .
}

SELECT (COUNT(?loan) AS ?n) WHERE {
  ?loan a <http://bird-bird_financial-ontology-20260804-131042/ontology/vkg-bird_financial/Loan> ;
        <http://bird-bird_financial-ontology-20260804-131042/ontology/vkg-bird_financial/Loan/amount> ?amount ;
        <http://bird-bird_financial-ontology-20260804-131042/ontology/vkg-bird_financial/Loan/date> ?date .
  FILTER(xsd:decimal(?amount) >= 250000)
  FILTER(?date >= "1995-01-01"^^xsd:date && ?date <= "1997-12-31"^^xsd:date)
}

