  ?district <http://bird-bird_financial-ontology-20260805-002537/ontology/vkg-bird_financial/District/a2> ?districtName .
}

SELECT (COUNT(*) AS ?n) WHERE {
  {
    SELECT ?district_id WHERE {
      ?d a <http://bird-bird_financial-ontology-20260805-002537/ontology/vkg-bird_financial/District> ;
         <http://bird-bird_financial-ontology-20260805-002537/ontology/vkg-bird_financial/District/district_id> ?district_id ;
         <http://bird-bird_financial-ontology-20260805-002537/ontology/vkg-bird_financial/District/a15> ?a15 .
    }
    ORDER BY DESC(xsd:integer(?a15))
    LIMIT 1 OFFSET 1
  }
  ?c a <http://bird-bird_financial-ontology-20260805-002537/ontology/vkg-bird_financial/Client> ;
     <http://bird-bird_financial-ontology-20260805-002537/ontology/vkg-bird_financial/Client/district_id> ?district_id ;
     <http://bird-bird_financial-ontology-20260805-002537/ontology/vkg-bird_financial/Client/gender> ?g .
