WHERE {
  {
    SELECT (COUNT(?c1) AS ?totalCount) WHERE {
      ?c1 a <http://bird-bird_financial-ontology-20260804-131042/ontology/vkg-bird_financial/Client> .
    }
  }
  {
    SELECT (COUNT(?c2) AS ?maleCount) WHERE {
      ?c2 a <http://bird-bird_financial-ontology-20260804-131042/ontology/vkg-bird_financial/Client> ;
          <http://bird-bird_financial-ontology-20260804-131042/ontology/vkg-bird_financial/Client/gender> "M" .
    }
  }
