SELECT ?account_id ?amount WHERE {
  ?loan a <http://bird-bird_financial-ontology-20260805-002537/ontology/vkg-bird_financial/Loan> ;
        <http://bird-bird_financial-ontology-20260805-002537/ontology/vkg-bird_financial/Loan/account_id> ?account_id ;
        <http://bird-bird_financial-ontology-20260805-002537/ontology/vkg-bird_financial/Loan/duration> ?duration ;
        <http://bird-bird_financial-ontology-20260805-002537/ontology/vkg-bird_financial/Loan/amount> ?amount .
  ?account a <http://bird-bird_financial-ontology-20260805-002537/ontology/vkg-bird_financial/Account> ;
           <http://bird-bird_financial-ontology-20260805-002537/ontology/vkg-bird_financial/Account/account_id> ?account_id ;
           <http://bird-bird_financial-ontology-20260805-002537/ontology/vkg-bird_financial/Account/date> ?date .
  FILTER(xsd:integer(?duration) > 12)
  FILTER(STRSTARTS(?date, "1993"))
  {
    SELECT (MAX(?amount2) AS ?maxAmount) WHERE {
      ?loan2 a <http://bird-bird_financial-ontology-20260805-002537/ontology/vkg-bird_financial/Loan> ;
             <http://bird-bird_financial-ontology-20260805-002537/ontology/vkg-bird_financial/Loan/account_id> ?account_id2 ;
             <http://bird-bird_financial-ontology-20260805-002537/ontology/vkg-bird_financial/Loan/duration> ?duration2 ;
             <http://bird-bird_financial-ontology-20260805-002537/ontology/vkg-bird_financial/Loan/amount> ?amount2 .
      ?account2 a <http://bird-bird_financial-ontology-20260805-002537/ontology/vkg-bird_financial/Account> ;
                <http://bird-bird_financial-ontology-20260805-002537/ontology/vkg-bird_financial/Account/account_id> ?account_id2 ;
                <http://bird-bird_financial-ontology-20260805-002537/ontology/vkg-bird_financial/Account/date> ?date2 .
      FILTER(xsd:integer(?duration2) > 12)
      FILTER(STRSTARTS(?date2, "1993"))
    }
  }
  FILTER(xsd:integer(?amount) = ?maxAmount)
}

SELECT DISTINCT ?client_id WHERE {
  ?t a <http://bird-bird_financial-ontology-20260804-131042/ontology/vkg-bird_financial/Trans> ;
     <http://bird-bird_financial-ontology-20260804-131042/ontology/vkg-bird_financial/Trans/operation> "credit card withdrawal" ;
     <http://bird-bird_financial-ontology-20260804-131042/ontology/vkg-bird_financial/Trans/date> ?date ;
     <http://bird-bird_financial-ontology-20260804-131042/ontology/vkg-bird_financial/Trans/amount> ?amt ;
     <http://bird-bird_financial-ontology-20260804-131042/ontology/vkg-bird_financial/Trans/account_id> ?accId .
  FILTER(SUBSTR(STR(?date),1,4) = "1998")

  ?disp a <http://bird-bird_financial-ontology-20260804-131042/ontology/vkg-bird_financial/Disp> ;
        <http://bird-bird_financial-ontology-20260804-131042/ontology/vkg-bird_financial/Disp/account_id> ?accId ;
        <http://bird-bird_financial-ontology-20260804-131042/ontology/vkg-bird_financial/Disp/type> "OWNER" ;
        <http://bird-bird_financial-ontology-20260804-131042/ontology/vkg-bird_financial/Disp/client_id> ?client_id .

  {
    SELECT (AVG(?amt2) AS ?avgAmt) WHERE {
      ?t2 a <http://bird-bird_financial-ontology-20260804-131042/ontology/vkg-bird_financial/Trans> ;
          <http://bird-bird_financial-ontology-20260804-131042/ontology/vkg-bird_financial/Trans/operation> "credit card withdrawal" ;
          <http://bird-bird_financial-ontology-20260804-131042/ontology/vkg-bird_financial/Trans/date> ?date2 ;
          <http://bird-bird_financial-ontology-20260804-131042/ontology/vkg-bird_financial/Trans/amount> ?amt2 .
      FILTER(SUBSTR(STR(?date2),1,4) = "1998")
    }
  }

  FILTER(xsd:decimal(?amt) < ?avgAmt)
}

