     <http://bird-bird_financial-ontology-20260804-131042/ontology/vkg-bird_financial/Client/gender> ?g .
  FILTER(?g = "M")
}

SELECT ?district_id ?amount WHERE {
  ?t a <http://bird-bird_financial-ontology-20260804-131042/ontology/vkg-bird_financial/Trans> ;
     <http://bird-bird_financial-ontology-20260804-131042/ontology/vkg-bird_financial/Trans/type> ?type ;
     <http://bird-bird_financial-ontology-20260804-131042/ontology/vkg-bird_financial/Trans/operation> ?operation ;
     <http://bird-bird_financial-ontology-20260804-131042/ontology/vkg-bird_financial/Trans/date> ?date ;
     <http://bird-bird_financial-ontology-20260804-131042/ontology/vkg-bird_financial/Trans/amount> ?amount ;
     <http://bird-bird_financial-ontology-20260804-131042/ontology/vkg-bird_financial/Trans/hasAccount> ?acc .
  FILTER(?type = "VYDAJ")
  FILTER(!BOUND(?operation) || !CONTAINS(LCASE(?operation), "credit card"))
  BIND(SUBSTR(STR(?date),1,7) AS ?month)
  FILTER(?month = "1996-01")
  ?d a <http://bird-bird_financial-ontology-20260804-131042/ontology/vkg-bird_financial/Disp> ;
     <http://bird-bird_financial-ontology-20260804-131042/ontology/vkg-bird_financial/Disp/hasAccount> ?acc ;
     <http://bird-bird_financial-ontology-20260804-131042/ontology/vkg-bird_financial/Disp/type> ?dtype ;
     <http://bird-bird_financial-ontology-20260804-131042/ontology/vkg-bird_financial/Disp/hasClient> ?cl .
  FILTER(?dtype = "OWNER")
  ?cl <http://bird-bird_financial-ontology-20260804-131042/ontology/vkg-bird_financial/Client/district_id> ?district_id .
}
ORDER BY DESC(xsd:decimal(?amount))
LIMIT 10

SELECT (AVG(?a15) AS ?avgCrimes1995) WHERE {
  {
