      ?d a <http://bird-bird_financial-ontology-20260805-002537/ontology/vkg-bird_financial/District> ;
         <http://bird-bird_financial-ontology-20260805-002537/ontology/vkg-bird_financial/District/a15> ?a15 ;
         <http://bird-bird_financial-ontology-20260805-002537/ontology/vkg-bird_financial/District/district_id> ?did .
      FILTER(xsd:decimal(?a15) > 4000)
      ?a a <http://bird-bird_financial-ontology-20260805-002537/ontology/vkg-bird_financial/Account> ;
         <http://bird-bird_financial-ontology-20260805-002537/ontology/vkg-bird_financial/Account/district_id> ?did ;
         <http://bird-bird_financial-ontology-20260805-002537/ontology/vkg-bird_financial/Account/date> ?adate .
      FILTER(SUBSTR(STR(?adate), 1, 4) >= "1997")
    }
  }
}

