  ?disp a <http://bird-bird_financial-ontology-20260804-131042/ontology/vkg-bird_financial/Disp> ;
        <http://bird-bird_financial-ontology-20260804-131042/ontology/vkg-bird_financial/Disp/client_id> "3356"^^xsd:integer ;
        <http://bird-bird_financial-ontology-20260804-131042/ontology/vkg-bird_financial/Disp/account_id> ?account_id .
  ?trans a <http://bird-bird_financial-ontology-20260804-131042/ontology/vkg-bird_financial/Trans> ;
