         <http://bird-bird_financial-ontology-20260804-131042/ontology/vkg-bird_financial/Trans/trans_id> ?trans_id ;
         <http://bird-bird_financial-ontology-20260804-131042/ontology/vkg-bird_financial/Trans/date> ?date ;
         <http://bird-bird_financial-ontology-20260804-131042/ontology/vkg-bird_financial/Trans/amount> ?amount ;
         <http://bird-bird_financial-ontology-20260804-131042/ontology/vkg-bird_financial/Trans/balance> ?balance ;
         <http://bird-bird_financial-ontology-20260804-131042/ontology/vkg-bird_financial/Trans/operation> ?operation ;
         <http://bird-bird_financial-ontology-20260804-131042/ontology/vkg-bird_financial/Trans/k_symbol> ?k_symbol .
