SELECT ?kind (COUNT(?t) AS ?cnt) (GROUP_CONCAT(DISTINCT ?k; separator=",") AS ?purpose)
WHERE {
  {
    BIND("statement_requests" AS ?kind)
    ?t a <http://bird-bird_financial-ontology-20260804-131042/ontology/vkg-bird_financial/Trans> ;
       <http://bird-bird_financial-ontology-20260804-131042/ontology/vkg-bird_financial/Trans/account_id> "3"^^xsd:integer ;
       <http://bird-bird_financial-ontology-20260804-131042/ontology/vkg-bird_financial/Trans/type> "VYDAJ" ;
       <http://bird-bird_financial-ontology-20260804-131042/ontology/vkg-bird_financial/Trans/k_symbol> ?k .
    FILTER(?k = "SLUZBY")
  }
  UNION
  {
    BIND("debit_3539" AS ?kind)
    ?t a <http://bird-bird_financial-ontology-20260804-131042/ontology/vkg-bird_financial/Trans> ;
       <http://bird-bird_financial-ontology-20260804-131042/ontology/vkg-bird_financial/Trans/account_id> "3"^^xsd:integer ;
       <http://bird-bird_financial-ontology-20260804-131042/ontology/vkg-bird_financial/Trans/amount> "3539"^^xsd:integer ;
       <http://bird-bird_financial-ontology-20260804-131042/ontology/vkg-bird_financial/Trans/k_symbol> ?k .
  }
}
GROUP BY ?kind

