  ?c a <http://bird-bird_financial-ontology-20260804-131042/ontology/vkg-bird_financial/Client> ;
     <http://bird-bird_financial-ontology-20260804-131042/ontology/vkg-bird_financial/Client/gender> "F" ;
     <http://bird-bird_financial-ontology-20260804-131042/ontology/vkg-bird_financial/Client/birth_date> ?bd ;
     <http://bird-bird_financial-ontology-20260804-131042/ontology/vkg-bird_financial/Client/client_id> ?cid .
  {
    SELECT (MIN(?bd2) AS ?minBd) WHERE {
      ?c2 a <http://bird-bird_financial-ontology-20260804-131042/ontology/vkg-bird_financial/Client> ;
          <http://bird-bird_financial-ontology-20260804-131042/ontology/vkg-bird_financial/Client/gender> "F" ;
          <http://bird-bird_financial-ontology-20260804-131042/ontology/vkg-bird_financial/Client/birth_date> ?bd2 .
    }
  }
  FILTER(?bd = ?minBd)
  ?d a <http://bird-bird_financial-ontology-20260804-131042/ontology/vkg-bird_financial/Disp> ;
     <http://bird-bird_financial-ontology-20260804-131042/ontology/vkg-bird_financial/Disp/client_id> ?cid ;
     <http://bird-bird_financial-ontology-20260804-131042/ontology/vkg-bird_financial/Disp/account_id> ?account_id .
