  ?card a <http://bird-bird_financial-ontology-20260804-131042/ontology/vkg-bird_financial/Card> ;
        <http://bird-bird_financial-ontology-20260804-131042/ontology/vkg-bird_financial/Card/type> "gold" ;
        <http://bird-bird_financial-ontology-20260804-131042/ontology/vkg-bird_financial/Card/hasDisp> ?disp .
