        <http://bird-bird_financial-ontology-20260804-131042/ontology/vkg-bird_financial/Disp/type> "OWNER" ;
        <http://bird-bird_financial-ontology-20260804-131042/ontology/vkg-bird_financial/Disp/hasClient> ?client .
