}

SELECT (((?sum1997 - ?sum1996) / ?sum1996) * 100 AS ?growthRatePercent)
WHERE {
  {
    SELECT
      (SUM(IF(?year = "1996", xsd:decimal(?amt), 0)) AS ?sum1996)
      (SUM(IF(?year = "1997", xsd:decimal(?amt), 0)) AS ?sum1997)
    WHERE {
      ?loan a <http://bird-bird_financial-ontology-20260804-131042/ontology/vkg-bird_financial/Loan> ;
            <http://bird-bird_financial-ontology-20260804-131042/ontology/vkg-bird_financial/Loan/amount> ?amt ;
            <http://bird-bird_financial-ontology-20260804-131042/ontology/vkg-bird_financial/Loan/date> ?date ;
            <http://bird-bird_financial-ontology-20260804-131042/ontology/vkg-bird_financial/Loan/hasAccount> ?acc .
      ?disp a <http://bird-bird_financial-ontology-20260804-131042/ontology/vkg-bird_financial/Disp> ;
            <http://bird-bird_financial-ontology-20260804-131042/ontology/vkg-bird_financial/Disp/hasAccount> ?acc ;
            <http://bird-bird_financial-ontology-20260804-131042/ontology/vkg-bird_financial/Disp/hasClient> ?client .
      ?client a <http://bird-bird_financial-ontology-20260804-131042/ontology/vkg-bird_financial/Client> ;
              <http://bird-bird_financial-ontology-20260804-131042/ontology/vkg-bird_financial/Client/gender> "M" .
      BIND(SUBSTR(STR(?date), 1, 4) AS ?year)
      FILTER(?year IN ("1996", "1997"))
    }
  }
}
